import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Utilità dei logaritmi","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/al/ala.md","filePath":"lezioni/a_algebra/al/ala.md"}`),a={name:`lezioni/a_algebra/al/ala.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="utilita-dei-logaritmi" tabindex="-1">Utilità dei logaritmi <a class="header-anchor" href="#utilita-dei-logaritmi" aria-label="Permalink to “Utilità dei logaritmi”">​</a></h1><p>Quando Nepero inventò i logaritmi i matematici contemporanei dissero che era stata loro regalata la metà della vita: infatti l&#39;occupazione principale dei matematici e soprattutto di quelli che si occupavano di astronomia ed astrologia (cioè di quasi tutti) era quella di calcolare la posizione dei pianeti, nel presente, nel passato e nel futuro e l&#39;espressione &quot;calcoli astronomici&quot; non era certo un modo di dire.</p><blockquote><p>Oggi, come oggi esistono i computer, non ci si rende conto di quanto sia importante il fare calcoli rapidamente ed in modo preciso; quando invece ho cominciato ad insegnare (nomina in matematica finanziaria ed attuariale) ancora non c&#39;erano nemmeno le calcolatrici tascabili e si usava il regolo calcolatore in legno; in quel periodo i logaritmi erano l&#39;unico modo per poter fare certi calcoli quali ad esempio il calcolo del montante di un capitale impiegato per un certo numero di anni oppure l&#39;interesse che ha permesso di formare una certa somma dopo un dato numero di anni.</p><p>Mi ricordo, all&#39;inizio della mia carriera scolastica, che uno studio di un architetto mi propose addirittura, come secondo lavoro, di ripassare i loro calcoli per controllarne la precisione, naturalmente rifiutai, ma questo vi fa capire qual era il bisogno di fare calcoli in modo rapido e preciso.</p></blockquote><p>I matematici possedevano le formule di prostaferesi che permettono di trasformare prodotti in somme e quindi di semplificare i calcoli, ma tali formule sono piuttosto complicate da applicare.</p><p>Con i logaritmi è possibile trasformare prodotti in somme, quozienti in differenze, elevamenti a potenza in prodotti e calcoli di radici in quozienti, quindi tutte le operazioni vengono molto semplificate.</p><blockquote><p>A questo aggiungiamo che i nostri sensi sono &quot;logaritmici&quot;: se ad esempio ascoltiamo un suono e sentiamo poi un altro suono che ci sembra di intensità doppia in effetti misurandolo ha intensità <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> volte superiore, la stessa cosa se vediamo una luce; se vediamo poi un&#39;altra luce che ci sembra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> volte più forte e misuriamo vediamo che è <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>9</mn></mrow><annotation encoding="application/x-tex">9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">9</span></span></span></span> volte più forte; cioè i nostri sensi sono in scala logaritmica, cosa che ci permette di poter avere uno spettro di sensazioni molto più ampio di quello che avremmo se i nostri sensi fossero lineari.</p><p>Utilizziamo i logaritmi nella vita di tutti i giorni, un esempio di logaritmo l&#39;hai sicuramente notato dal gommista: quando ti misura la pressione di una gomma sul suo strumento la scala non è lineare ma è logaritmica; ma prova anche a guardare le scale sulla tua macchina fotografica.</p><p>Qui sotto ti faccio un esempio di scala logaritmica, prova a pensare in quanti strumenti hai visto qualcosa del genere:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>0</mn><mspace width="1em"></mspace><mn>1</mn><mspace width="1em"></mspace><mn>2</mn><mspace width="1em"></mspace><mn>4</mn><mspace width="1em"></mspace><mn>8</mn><mspace width="1em"></mspace><mn>16</mn></mrow><annotation encoding="application/x-tex">0 \\quad 1 \\quad 2 \\quad 4 \\quad 8 \\quad 16 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:1em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:1em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:1em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:1em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:1em;"></span><span class="mord">16</span></span></span></span></span></p></blockquote>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};